module cell_answer (\n    input [7:0] matrix00, matrix01, matrix02, matrix03,\n    input [7:0] matrix10, matrix11, matrix12, matrix13,\n    input [7:0] matrix20, matrix21, matrix22, matrix23,\n    input [7:0] matrix30, matrix31, matrix32, matrix33,\n    output [7:0] answer00, answer01, answer02, answer03,\n    output [7:0] answer10, answer11, answer12, answer13,\n    output [7:0] answer20, answer21, answer22, answer23,\n    output [7:0] answer30, answer31, answer32, answer33\n);\n\n    module comp #(parameter WIDTH=8) (input [WIDTH-1:0] a, b, output [WIDTH-1:0] min, max);\n        assign min = (a < b) ? a : b;\n        assign max = (a < b) ? b : a;\n    endmodule\n\n    module vector_processor (\n        input [7:0] a0, a1, a2, a3,\n        output [1:0] rank0, rank1, rank2, rank3,\n        output [2:0] u_count\n    );\n        wire [7:0] t0, t1, t2, t3, u0, u1, u2, u3;\n        wire [7:0] s0, s1, s2, s3;\n\n        comp cmp01 (.a(a0), .b(a1), .min(t0), .max(t1));\n        comp cmp23 (.a(a2), .b(a3), .min(t2), .max(t3));\n        comp cmp02 (.a(t0), .b(t2), .min(u0), .max(u2));\n        comp cmp13 (.a(t1), .b(t3), .min(u1), .max(u3));\n        comp cmp12 (.a(u1), .b(u2), .min(s1), .max(s2));\n        assign s0 = u0;\n        assign s3 = u3;\n\n        wire u0_valid = 1'b1;\n        wire u1_valid = (s1 != s0);\n        wire u2_valid = (s2 != s1);\n        wire u3_valid = (s3 != s2);\n\n        assign u_count = {1'b0,u0_valid} + {1'b0,u1_valid} + {1'b0,u2_valid} + {1'b0,u3_valid};\n\n        assign rank0 = (u0_valid & (s0 < a0)) + (u1_valid & (s1 < a0)) + (u2_valid & (s2 < a0)) + (u3_valid & (s3 < a0));\n        assign rank1 = (u0_valid & (s0 < a1)) + (u1_valid & (s1 < a1)) + (u2_valid & (s2 < a1)) + (u3_valid & (s3 < a1));\n        assign rank2 = (u0_valid & (s0 < a2)) + (u1_valid & (s1 < a2)) + (u2_valid & (s2 < a2)) + (u3_valid & (s3 < a2));\n        assign rank3 = (u0_valid & (s0 < a3)) + (u1_valid & (s1 < a3)) + (u2_valid & (s2 < a3)) + (u3_valid & (s3 < a3));\n    endmodule\n\n    wire [1:0] row0_rank0, row0_rank1, row0_rank2, row0_rank3;\n    wire [2:0] row0_u_count;\n    wire [1:0] row1_rank0, row1_rank1, row1_rank2, row1_rank3;\n    wire [2:0] row1_u_count;\n    wire [1:0] row2_rank0, row2_rank1, row2_rank2, row2_rank3;\n    wire [2:0] row2_u_count;\n    wire [1:0] row3_rank0, row3_rank1, row3_rank2, row3_rank3;\n    wire [2:0] row3_u_count;\n\n    wire [1:0] col0_rank0, col0_rank1, col0_rank2, col0_rank3;\n    wire [2:0] col0_u_count;\n    wire [1:0] col1_rank0, col1_rank1, col1_rank2, col1_rank3;\n    wire [2:0] col1_u_count;\n    wire [1:0] col2_rank0, col2_rank1, col2_rank2, col2_rank3;\n    wire [2:0] col2_u_count;\n    wire [1:0] col3_rank0, col3_rank1, col3_rank2, col3_rank3;\n    wire [2:0] col3_u_count;\n\n    vector_processor row0 (\n        .a0(matrix00), .a1(matrix01), .a2(matrix02), .a3(matrix03),\n        .rank0(row0_rank0), .rank1(row0_rank1), .rank2(row0_rank2), .rank3(row0_rank3),\n        .u_count(row0_u_count)\n    );\n\n    vector_processor row1 (\n        .a0(matrix10), .a1(matrix11), .a2(matrix12), .a3(matrix13),\n        .rank0(row1_rank0), .rank1(row1_rank1), .rank2(row1_rank2), .rank3(row1_rank3),\n        .u_count(row1_u_count)\n    );\n\n    vector_processor row2 (\n        .a0(matrix20), .a1(matrix21), .a2(matrix22), .a3(matrix23),\n        .rank0(row2_rank0), .rank1(row2_rank1), .rank2(row2_rank2), .rank3(row2_rank3),\n        .u_count(row2_u_count)\n    );\n\n    vector_processor row3 (\n        .a0(matrix30), .a1(matrix31), .a2(matrix32), .a3(matrix33),\n        .rank0(row3_rank0), .rank1(row3_rank1), .rank2(row3_rank2), .rank3(row3_rank3),\n        .u_count(row3_u_count)\n    );\n\n    vector_processor col0 (\n        .a0(matrix00), .a1(matrix10), .a2(matrix20), .a3(matrix30),\n        .rank0(col0_rank0), .rank1(col0_rank1), .rank2(col0_rank2), .rank3(col0_rank3),\n        .u_count(col0_u_count)\n    );\n\n    vector_processor col1 (\n        .a0(matrix01), .a1(matrix11), .a2(matrix21), .a3(matrix31),\n        .rank0(col1_rank0), .rank1(col1_rank1), .rank2(col1_rank2), .rank3(col1_rank3),\n        .u_count(col1_u_count)\n    );\n\n    vector_processor col2 (\n        .a0(matrix02), .a1(matrix12), .a2(matrix22), .a3(matrix32),\n        .rank0(col2_rank0), .rank1(col2_rank1), .rank2(col2_rank2), .rank3(col2_rank3),\n        .u_count(col2_u_count)\n    );\n\n    vector_processor col3 (\n        .a0(matrix03), .a1(matrix13), .a2(matrix23), .a3(matrix33),\n        .rank0(col3_rank0), .rank1(col3_rank1), .rank2(col3_rank2), .rank3(col3_rank3),\n        .u_count(col3_u_count)\n    );\n\n    assign answer00 = (row0_rank0 > col0_rank0 ? row0_rank0 : col0_rank0) + (row0_u_count - row0_rank0 > col0_u_count - col0_rank0 ? row0_u_count - row0_rank0 : col0_u_count - col0_rank0);\n    assign answer01 = (row0_rank1 > col1_rank0 ? row0_rank1 : col1_rank0) + (row0_u_count - row0_rank1 > col1_u_count - col1_rank0 ? row0_u_count - row0_rank1 : col1_u_count - col1_rank0);\n    assign answer02 = (row0_rank2 > col2_rank0 ? row0_rank2 : col2_rank0) + (row0_u_count - row0_rank2 > col2_u_count - col2_rank0 ? row0_u_count - row0_rank2 : col2_u_count - col2_rank0);\n    assign answer03 = (row0_rank3 > col3_rank0 ? row0_rank3 : col3_rank0) + (row0_u_count - row0_rank3 > col3_u_count - col3_rank0 ? row0_u_count - row0_rank3 : col3_u_count - col3_rank0);\n\n    assign answer10 = (row1_rank0 > col0_rank1 ? row1_rank0 : col0_rank1) + (row1_u_count - row1_rank0 > col0_u_count - col0_rank1 ? row1_u_count - row1_rank0 : col0_u_count - col0_rank1);\n    assign answer11 = (row1_rank1 > col1_rank1 ? row1_rank1 : col1_rank1) + (row1_u_count - row1_rank1 > col1_u_count - col1_rank1 ? row1_u_count - row1_rank1 : col1_u_count - col1_rank1);\n    assign answer12 = (row1_rank2 > col2_rank1 ? row1_rank2 : col2_rank1) + (row1_u_count - row1_rank2 > col2_u_count - col2_rank1 ? row1_u_count - row1_rank2 : col2_u_count - col2_rank1);\n    assign answer13 = (row1_rank3 > col3_rank1 ? row1_rank3 : col3_rank1) + (row1_u_count - row1_rank3 > col3_u_count - col3_rank1 ? row1_u_count - row1_rank3 : col3_u_count - col3_rank1);\n\n    assign answer20 = (row2_rank0 > col0_rank2 ? row2_rank0 : col0_rank2) + (row2_u_count - row2_rank0 > col0_u_count - col0_rank2 ? row2_u_count - row2_rank0 : col0_u_count - col0_rank2);\n    assign answer21 = (row2_rank1 > col1_rank2 ? row2_rank1 : col1_rank2) + (row2_u_count - row2_rank1 > col1_u_count - col1_rank2 ? row2_u_count - row2_rank1 : col1_u_count - col1_rank2);\n    assign answer22 = (row2_rank2 > col2_rank2 ? row2_rank2 : col2_rank2) + (row2_u_count - row2_rank2 > col2_u_count - col2_rank2 ? row2_u_count - row2_rank2 : col2_u_count - col2_rank2);\n    assign answer23 = (row2_rank3 > col3_rank2 ? row2_rank3 : col3_rank2) + (row2_u_count - row2_rank3 > col3_u_count - col3_rank2 ? row2_u_count - row2_rank3 : col3_u_count - col3_rank2);\n\n    assign answer30 = (row3_rank0 > col0_rank3 ? row3_rank0 : col0_rank3) + (row3_u_count - row3_rank0 > col0_u_count - col0_rank3 ? row3_u_count - row3_rank0 : col0_u_count - col0_rank3);\n    assign answer31 = (row3_rank1 > col1_rank3 ? row3_rank1 : col1_rank3) + (row3_u_count - row3_rank1 > col1_u_count - col1_rank3 ? row3_u_count - row3_rank1 : col1_u_count - col1_rank3);\n    assign answer32 = (row3_rank2 > col2_rank3 ? row3_rank2 : col2_rank3) + (row3_u_count - row3_rank2 > col2_u_count - col2_rank3 ? row3_u_count - row3_rank2 : col2_u_count - col2_rank3);\n    assign answer33 = (row3_rank3 > col3_rank3 ? row3_rank3 : col3_rank3) + (row3_u_count - row3_rank3 > col3_u_count - col3_rank3 ? row3_u_count - row3_rank3 : col3_u_count - col3_rank3);\n\nendmodule